<script setup lang="ts">import { inject } from 'vue'; import type { TraceGlow } from '@trace-glow/vue'; const telemetry = inject<TraceGlow>('trace-glow')!; const log = () => telemetry.logger.info('demo.vue.log'); const fail = () => { throw new Error('Vue demo error'); };</script><template><main><h1>Vue demo</h1><button @click="log">Capture log</button><button @click="fail">Trigger Vue error</button></main></template>
